<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $routes = []; foreach(app("router")->getRoutes() as $r) { $routes[] = ["uri" => $r->uri(), "methods" => $r->methods(), "action" => $r->getActionName(), "name" => $r->getName(), "middleware" => $r->middleware()]; } file_put_contents("routes_data.json", json_encode($routes, JSON_PRETTY_PRINT));
